UPDATE catalog.catalog_group g SET last_value = GREATEST(g.last_value,
    COALESCE((SELECT MAX(i.value) FROM catalog.catalog_item i WHERE i.group_id = g.id), 0));

CREATE TEMP TABLE testq_rows (
    id uuid PRIMARY KEY, code text NOT NULL, type text NOT NULL,
    subject_id uuid NOT NULL, grade_id uuid NOT NULL, level_id uuid NOT NULL,
    task_type_id uuid, points numeric(8,4) NOT NULL, content text NOT NULL,
    plain text NOT NULL, body jsonb NOT NULL, parent_id uuid, position integer,
    seed_status text NOT NULL, knowledge_ids uuid[] NOT NULL DEFAULT '{}',
    tag_ids uuid[] NOT NULL DEFAULT '{}') ON COMMIT DROP;

INSERT INTO testq_rows (id, code, type, subject_id, grade_id, level_id, task_type_id, points, content, plain, body, parent_id, position, seed_status, knowledge_ids, tag_ids)
SELECT md5('thi360-testq-' || seeded.code)::uuid, seeded.code, 'SINGLE_CHOICE', '00000000-0000-7000-8200-000000000201',
       (ARRAY['00000000-0000-7000-8200-000000000301','00000000-0000-7000-8200-000000000301','00000000-0000-7000-8200-000000000301','00000000-0000-7000-8200-000000000301','00000000-0000-7000-8200-000000000302','00000000-0000-7000-8200-000000000302','00000000-0000-7000-8200-000000000302','00000000-0000-7000-8200-000000000302','00000000-0000-7000-8200-000000000303','00000000-0000-7000-8200-000000000303','00000000-0000-7000-8200-000000000303','00000000-0000-7000-8200-000000000303']::uuid[])[1 + (n - 1) % 12], (ARRAY['00000000-0000-7000-8200-000000000401','00000000-0000-7000-8200-000000000402','00000000-0000-7000-8200-000000000403','00000000-0000-7000-8200-000000000404']::uuid[])[1 + (n - 1) % 4],
       '00000000-0000-7000-8200-000000000601', 1, '<p>' || seeded.code || ' content</p>',
       seeded.code || ' content' || ' One Two', '{"type":"SINGLE_CHOICE","options":[{"id":"a","content":"<p>One</p>","correct":true},{"id":"b","content":"<p>Two</p>","correct":false}]}'::jsonb,
       NULL, NULL, 'READY', '{}', '{}'
FROM generate_series(1, 108) AS series(n)
CROSS JOIN LATERAL (SELECT 'TESTQ-TOAN-MC1-' || lpad(n::text, GREATEST(3, length(n::text)), '0') AS code) seeded;

