WITH inserted AS (INSERT INTO questionbank.question (id, code, type, status, parent_id, position,
    subject_item_id, grade_item_id, level_item_id, task_type_item_id, points,
    current_version_no, working_version_no, content_text, search_text)
SELECT id, code, type, seed_status, NULL, NULL, subject_id, grade_id, level_id,
       task_type_id, points,
       CASE WHEN seed_status = 'DRAFT' THEN NULL ELSE 1 END,
       CASE WHEN seed_status = 'DRAFT' THEN 1 ELSE NULL END,
       plain, lower(code || ' ' || plain)
FROM testq_rows WHERE parent_id IS NULL
ON CONFLICT DO NOTHING RETURNING subject_item_id, status)
INSERT INTO questionbank.question_source_revision (subject_item_id, revision)
SELECT subject_item_id, count(*) FROM inserted WHERE status = 'READY' GROUP BY subject_item_id
ON CONFLICT (subject_item_id) DO UPDATE
SET revision = questionbank.question_source_revision.revision + EXCLUDED.revision;

INSERT INTO questionbank.question (id, code, type, status, parent_id, position,
    subject_item_id, grade_item_id, level_item_id, task_type_item_id, points,
    current_version_no, working_version_no, content_text, search_text)
SELECT id, code, type, seed_status, parent_id, position, subject_id, grade_id, level_id,
       task_type_id, points, CASE WHEN seed_status = 'DRAFT' THEN NULL ELSE 1 END,
       CASE WHEN seed_status = 'DRAFT' THEN 1 ELSE NULL END, plain, lower(code || ' ' || plain)
FROM testq_rows WHERE parent_id IS NOT NULL
ON CONFLICT DO NOTHING;

INSERT INTO questionbank.question_version (question_id, version_no, snapshot, ready_at)
SELECT s.id, 1, jsonb_build_object(
    'subjectItemId', s.subject_id, 'gradeItemId', s.grade_id, 'levelItemId', s.level_id,
    'taskTypeItemId', s.task_type_id, 'competencyItemId', NULL, 'points', s.points,
    'knowledge', COALESCE((SELECT jsonb_agg(jsonb_build_object('itemId', k, 'primary', k = s.knowledge_ids[1]))
        FROM unnest(s.knowledge_ids) k), '[]'::jsonb),
    'tagItemIds', COALESCE(to_jsonb(s.tag_ids), '[]'::jsonb), 'content', s.content,
    'solution', NULL, 'commonMistakes', '[]'::jsonb, 'attachmentIds', '[]'::jsonb,
    'body', s.body, 'sourceCode', NULL),
    CASE WHEN q.status = 'DRAFT' THEN NULL ELSE now() END
FROM testq_rows s JOIN questionbank.question q ON q.id = s.id
ON CONFLICT DO NOTHING;

INSERT INTO questionbank.question_knowledge (question_id, knowledge_item_id, is_primary)
SELECT s.id, k, k = s.knowledge_ids[1] FROM testq_rows s
    JOIN questionbank.question q ON q.id = s.id CROSS JOIN LATERAL unnest(s.knowledge_ids) k
ON CONFLICT DO NOTHING;

INSERT INTO questionbank.question_tag (question_id, tag_item_id)
SELECT s.id, t FROM testq_rows s JOIN questionbank.question q ON q.id = s.id
    CROSS JOIN LATERAL unnest(s.tag_ids) t
ON CONFLICT DO NOTHING;


